UPDATE membership_usage_monthly
SET
    chat_used_count = chat_used_count + 1,
    updated_date = NOW()
WHERE member_id = #{memberId}
  AND usage_month = #{usageMonth}

UPDATE membership_usage_monthly
SET
    chat_phone_used_count = chat_phone_used_count + 1,
    updated_date = NOW()
WHERE member_id = #{memberId}
  AND usage_month = #{usageMonth}

UPDATE membership_usage_monthly
SET
    inquiry_used_count = inquiry_used_count + 1,
    updated_date = NOW()
WHERE member_id = #{memberId}
  AND usage_month = #{usageMonth}
